import fs from "node:fs/promises";
import path from "node:path";
import assert from "node:assert/strict";
const cwd=process.cwd(), state=process.env.LLV_STATE_DIR!, at="2026-10-19T00:00:00.000Z";
const load=(name:string)=>import(path.join(cwd,"src/lib",name));
const home=path.join(process.env.TMPDIR!,"compiled-home"), memory=path.join(home,"projects","compiled-fixture","memory");
await fs.mkdir(memory,{recursive:true});
const body="Inspect ownership before changing a retained worker.\n";
await fs.writeFile(path.join(memory,"MEMORY.md"),"- [Topic](topic.md)\n");await fs.writeFile(path.join(memory,"topic.md"),body);
const id="compiled-import-fixture";
await fs.writeFile(path.join(state,"memory-source.json"),JSON.stringify({schemaVersion:1,source:"delegatus",phase:"importing",importId:id,changedAt:at}));
async function worker(name:string, frame:unknown){
 const child=Bun.spawn([process.execPath,path.join(cwd,".next/server",name)],{env:{...process.env},stdin:"pipe",stdout:"pipe",stderr:"pipe"});
 const deadline=setTimeout(()=>child.kill("SIGTERM"),60000);
 try {
  child.stdin.write(JSON.stringify(frame)+"\n"); child.stdin.end();
  const [out,err,exit]=await Promise.all([new Response(child.stdout).text(),new Response(child.stderr).text(),child.exited]);
  assert.equal(exit,0,`compiled worker failed: ${err} ${out}`);
  return out.trim().split("\n").map(line=>JSON.parse(line));
 }finally{clearTimeout(deadline);}
}
const request={importId:id,previous:null,roots:{claudeHomes:[home],codexHomes:[]},at};
assert.equal((await worker("memory-import-worker.js",request)).at(-1).result.state,"ready");
const {readImportCandidates,writeImportRows}=await load("memory/importStore.ts");
const rows=readImportCandidates(id).candidates;assert.equal(rows.length,1);
await writeImportRows(rows.map((row:any)=>({...row,dispositions:[{at,pass:"compiled-disposition",kind:"drop",ruleIds:[],occurrences:row.occurrences.map((o:any)=>o.id),reason:"task-specific",note:"The fixture narrates one task."}]})));
await worker("memory-import-worker.js",{...request,advance:true});
assert.equal(JSON.parse(await fs.readFile(path.join(state,"memory-source.json"),"utf8")).phase,"active");
assert.equal(await fs.readFile(path.join(memory,"topic.md"),"utf8"),body);
const {seedImport,importCandidate,IMPORT_AT,IMPORT_PROJECT}=await load("memory/fixtures/import.ts");
const candidate=importCandidate(1);await seedImport([candidate]);
const {claimPass,patchPass}=await load("memory/curation/store.ts");
const {readCuration}=await load("memory/curation/read.ts");
const {applyCuration}=await load("memory/curation/apply.ts");
const pass=claimPass({project:IMPORT_PROJECT,repoDir:null,now:Date.parse(IMPORT_AT)});assert.ok(pass);
await readCuration(pass,"imports");
applyCuration(pass,{scopes:[{scope:candidate.suggestedScope,revision:0,order:[`adopt:${candidate.id}:0`]}],adopt:[{candidate:candidate.id,occurrences:candidate.occurrences.map((o:any)=>o.id),parts:[{to:candidate.suggestedScope,rule:"Inspect ownership before changing a retained worker.",why:"This condition applies to recurring ownership changes."}],note:"Retain the ownership check."}]},IMPORT_AT);
const live=await worker("task-page-worker.js",{id:1,request:{kind:"curation-undo",passId:pass.id}});assert.equal(live.at(-1).curationRefusal,"CURATE_LIVE");
patchPass(pass.id,{state:"succeeded",endedAt:"2026-10-19T00:00:00.001Z"});
const undo=await worker("task-page-worker.js",{id:2,request:{kind:"curation-undo",passId:pass.id}});
assert.equal(undo.at(-1).result.value.importUndo.state,"undone");
console.log(JSON.stringify({compiledImport:true,compiledAdvance:true,sourceUnchanged:true,compiledUndo:true,liveUndoRefused:true}));
